parameters.query:
let rows = AzMaintenance_Events({IncludeSynthetic})
    | summarize by subscription_id
    | project value = subscription_id, label = subscription_id;
let n = toscalar(rows | count);
rows
| union (print value = "(no data yet)", label = "(no data yet)" | where n == 0)

let rows = AzMaintenance_Catalog({IncludeSynthetic})
    | summarize by category
    | project value = category, label = category;
let n = toscalar(rows | count);
rows
| union (print value = "(no data yet)", label = "(no data yet)" | where n == 0)

let rows = AzMaintenance_EventServices({IncludeSynthetic})
    | summarize by region
    | project value = region, label = region;
let n = toscalar(rows | count);
rows
| union (print value = "(no data yet)", label = "(no data yet)" | where n == 0)
| order by label asc

content.query:
let win_days = toint(datetime_diff("day", {TimeRange:end}, {TimeRange:start}));
let es = AzMaintenance_EventServices({IncludeSynthetic})
    | where impact_start_utc between ({TimeRange:start} .. {TimeRange:end})
    | where '*' in ({Subscriptions}) or subscription_id in ({Subscriptions})
    | where '*' in ({Category}) or category in ({Category})
    | where '*' in ({Service}) or service in ({Service})
    | where '*' in ({Region}) or region in ({Region});
let avail = AzMaintenance_Availability(win_days, {IncludeUserInitiated}, {IncludeSynthetic})
    | where '*' in ({Category}) or category in ({Category})
    | where '*' in ({Service}) or service_name in ({Service});
let iv = AzMaintenance_ResourceIntervals({IncludeSynthetic})
    | where '*' in ({Subscriptions}) or subscription_id in ({Subscriptions})
    | where '*' in ({Category}) or category in ({Category})
    | where '*' in ({Service}) or service_name in ({Service})
    | where end_utc > {TimeRange:start} and start_utc < {TimeRange:end}
    | where {IncludeUserInitiated} or not(user_initiated);
let ev = es | summarize exposure_h = max(exposure_h), is_open = max(toint(is_open)) by tracking_id, class;
let unplanned = toscalar(ev | where class == "Unplanned" | summarize dcount(tracking_id));
let planned = toscalar(ev | where class == "Planned" | summarize dcount(tracking_id));
let exposure = toscalar(ev | where class == "Unplanned" | summarize round(sum(exposure_h), 1));
let open_n = toscalar(ev | where is_open == 1 and class in ("Planned", "Unplanned") | summarize dcount(tracking_id));
let down_min = toscalar(iv | where state =~ "Unavailable" and not(stale_open) | summarize round(coalesce(sum(minutes), 0.0), 1));
let av = toscalar(avail | summarize d = sum(downtime_min), r = sum(resources) | project a = iff(r > 0, round((1.0 - d / (r * win_days * 1440.0)) * 100.0, 3), real(null)));
let trend_u = toscalar(es | where class == "Unplanned" | make-series n = dcount(tracking_id) default = 0 on impact_start_utc from {TimeRange:start} to {TimeRange:end} step 7d | project n);
let trend_p = toscalar(es | where class == "Planned" | make-series n = dcount(tracking_id) default = 0 on impact_start_utc from {TimeRange:start} to {TimeRange:end} step 7d | project n);
let trend_d = toscalar(iv | where state =~ "Unavailable" and not(stale_open) | make-series n = sum(minutes) default = 0.0 on start_utc from {TimeRange:start} to {TimeRange:end} step 7d | project n);
let trend_x = toscalar(es | where class == "Unplanned" | summarize h = max(exposure_h), s = min(impact_start_utc) by tracking_id
    | make-series n = sum(h) default = 0.0 on s from {TimeRange:start} to {TimeRange:end} step 7d | project n);
datatable(order: int)[1, 2, 3, 4, 5, 6]
| extend metric = case(order == 1, "Unplanned events", order == 2, "Planned maintenance", order == 3, "Observed downtime (minutes)",
                       order == 4, "Observed availability (%)", order == 5, "Open right now", "Event time open (hours)"),
         value = case(order == 1, todouble(unplanned), order == 2, todouble(planned), order == 3, todouble(down_min),
                      order == 4, todouble(av), order == 5, todouble(open_n), todouble(exposure)),
         subtitle = case(order == 1, "Azure incidents nobody scheduled",
                         order == 2, "Maintenance Azure announced in advance",
                         order == 3, "Minutes your resources were reported Unavailable",
                         order == 4, iff(isnull(av), "No resource inventory yet", "Share of time your resources were up"),
                         order == 5, "Incidents and maintenance not yet resolved",
                         "How long events were open (not downtime)"),
         status = case(order == 1, iff(unplanned == 0, "good", "warn"),
                       order == 2, "info",
                       order == 3, iff(down_min == 0, "good", "warn"),
                       order == 4, iff(isnull(av), "info", iff(av >= 99.9, "good", iff(av >= 99.0, "warn", "bad"))),
                       order == 5, iff(open_n == 0, "good", "warn"),
                       "info"),
         trend = case(order == 1, trend_u, order == 2, trend_p, order == 3, trend_d, order == 6, trend_x, dynamic(null)),
         go = case(order == 1, "timeline", order == 2, "planned", order == 3, "resources", order == 4, "services", "timeline")
| project order, metric, value, subtitle, status, trend, go
| order by order asc

let iv = AzMaintenance_ResourceIntervals({IncludeSynthetic})
    | where '*' in ({Subscriptions}) or subscription_id in ({Subscriptions})
    | where '*' in ({Category}) or category in ({Category})
    | where '*' in ({Service}) or service_name in ({Service})
    | where end_utc > {TimeRange:start} and start_utc < {TimeRange:end}
    | where {IncludeUserInitiated} or not(user_initiated);
iv
| where state =~ "Unavailable" and not(stale_open)
| summarize downtime_min = round(sum(minutes), 1) by month = startofmonth(start_utc), class
| order by month asc

let win_days = toint(datetime_diff("day", {TimeRange:end}, {TimeRange:start}));
let avail = AzMaintenance_Availability(win_days, {IncludeUserInitiated}, {IncludeSynthetic})
    | where '*' in ({Category}) or category in ({Category})
    | where '*' in ({Service}) or service_name in ({Service});
avail
| where downtime_min > 0
| top 10 by downtime_min desc
| project service_name, downtime_min

let win_days = toint(datetime_diff("day", {TimeRange:end}, {TimeRange:start}));
let es = AzMaintenance_EventServices({IncludeSynthetic})
    | where impact_start_utc between ({TimeRange:start} .. {TimeRange:end})
    | where '*' in ({Subscriptions}) or subscription_id in ({Subscriptions})
    | where '*' in ({Category}) or category in ({Category})
    | where '*' in ({Service}) or service in ({Service})
    | where '*' in ({Region}) or region in ({Region});
let avail = AzMaintenance_Availability(win_days, {IncludeUserInitiated}, {IncludeSynthetic})
    | where '*' in ({Category}) or category in ({Category})
    | where '*' in ({Service}) or service_name in ({Service});
let trend_by_service = es | where class in ("Planned", "Unplanned")
    | make-series trend = dcount(tracking_id) default = 0 on impact_start_utc from {TimeRange:start} to {TimeRange:end} step 7d by service;
let per_event = es | where class in ("Planned", "Unplanned") | summarize exposure_h = max(exposure_h), class = take_any(class) by tracking_id, service, category;
per_event
| summarize events = dcount(tracking_id), unplanned = dcountif(tracking_id, class == "Unplanned"), planned = dcountif(tracking_id, class == "Planned"),
            exposure_p50_h = round(percentile(exposure_h, 50), 1), exposure_p90_h = round(percentile(exposure_h, 90), 1) by service, category
| join kind=leftouter (trend_by_service | project service, trend) on service
| project-away service1
| join kind=fullouter (avail | project service = service_name, category, resources, downtime_min, availability_pct, sla_percent, sla_status, approximate) on service
| project category = coalesce(category, category1), service = coalesce(service, service1), trend, events = coalesce(events, 0), unplanned = coalesce(unplanned, 0),
          planned = coalesce(planned, 0), exposure_p50_h, exposure_p90_h, resources, downtime_min, availability_pct, sla_percent, sla_status, approximate
| order by category asc, events desc

let p = AzMaintenance_Planned({IncludeSynthetic})
    | where '*' in ({Subscriptions}) or subscription_id in ({Subscriptions})
    | summarize arg_min(window_start_utc, *) by tracking_id;
let in_range = p | where not(upcoming) and window_start_utc between ({TimeRange:start} .. {TimeRange:end});
let soon = toscalar(p | where upcoming and window_start_utc < now() + 30d | summarize dcount(tracking_id));
let notices = toscalar(in_range | summarize dcount(tracking_id));
let lead = toscalar(in_range | where lead_time_days >= 0 | summarize round(avg(lead_time_days), 1));
let sched = toscalar(in_range | summarize round(sum(scheduled_h), 1));
let realised = toscalar(in_range | summarize round(sum(realised_downtime_min), 1));
let measured = toscalar(in_range | summarize countif(isnotnull(realised_downtime_min)));
datatable(order: int)[1, 2, 3, 4, 5]
| extend metric = case(order == 1, "Starting in the next 30 days", order == 2, "Maintenance notices in range", order == 3, "Typical notice (days)",
                       order == 4, "Scheduled windows (hours)", "Realised downtime (minutes)"),
         value = case(order == 1, todouble(soon), order == 2, todouble(notices), order == 3, todouble(lead), order == 4, todouble(sched), todouble(realised)),
         subtitle = case(order == 1, "Upcoming planned maintenance",
                         order == 2, "Announced maintenance in the selected range",
                         order == 3, "How far ahead the ledger saw the notice",
                         order == 4, "Planned windows, not downtime",
                         iff(measured == 0, "Not measured: no overlapping Resource Health data", "Unavailable time during maintenance, your resources")),
         status = case(order == 1, iff(soon > 0, "info", "good"), order == 5, iff(measured == 0, "info", iff(coalesce(realised, 0.0) == 0, "good", "warn")), "info")
| project order, metric, value, subtitle, status
| order by order asc

let p = AzMaintenance_PirBaseline({IncludeSynthetic});
let total = toscalar(p | count);
let med = toscalar(p | where isnotnull(duration_h) | summarize round(percentile(duration_h, 50), 1));
let p90 = toscalar(p | where isnotnull(duration_h) | summarize round(percentile(duration_h, 90), 1));
let mx = toscalar(p | where isnotnull(duration_h) | summarize round(max(duration_h), 1));
let last_pir = toscalar(p | summarize max(published_date));
datatable(order: int)[1, 2, 3, 4, 5]
| extend metric = case(order == 1, "Public PIRs published", order == 2, "Typical incident (hours)", order == 3, "Long incident, 9 in 10 shorter (hours)",
                       order == 4, "Longest incident (hours)", "Days since the latest PIR"),
         value = case(order == 1, todouble(total), order == 2, todouble(med), order == 3, todouble(p90), order == 4, todouble(mx),
                      todouble(datetime_diff("day", now(), last_pir))),
         subtitle = case(order == 1, "Azure-wide, broad-impact incidents only", order == 2, "Half of incidents were shorter than this",
                         order == 3, "Planning figure for a bad incident", order == 4, "Longest window read from a PIR", "Most recent public PIR"),
         status = "info"
| project order, metric, value, subtitle, status
| order by order asc

