content.query:
let fc = AzMaintenance_Forecast({IncludeSynthetic});
let cat = AzMaintenance_Catalog({IncludeSynthetic}) | summarize category = take_any(category) by service_name;
let svc = '{PlannerService}';
let reg = '{PlannerRegion}';
let svc_cat = toscalar(cat | where service_name == svc | project category);
let rank = (level: string) { case(level == "service_region", 1, level == "service", 2, 3) };
let customer = fc
    | where baseline == "customer"
    | where (scope_level == "service_region" and scope_key == strcat(svc, "|", reg))
         or (scope_level == "service" and scope_key == svc)
         or (scope_level == "category" and scope_key == coalesce(svc_cat, ""))
    | extend r = rank(scope_level)
    | order by r asc
    | extend picked = row_number() == 1;
let weak = toscalar(customer | where picked | project confidence in ("insufficient", "low"));
let pir = fc
    | where baseline == "public_pir" and (scope_key == coalesce(svc_cat, "") or scope_key == "(all categories)")
    | where coalesce(weak, true)
    | extend picked = false;
let rows = union (customer | extend basis = "Your estate"), (pir | extend basis = "Azure-wide PIR baseline, not your estate")
    | extend mean_over_horizon_h = round(mean_annual_h * {PlannerHorizon}, 2),
             note = case(basis startswith "Azure-wide", "Broad-impact incidents only; shown because your history is thin.",
                         picked, "Preferred scope (most specific with data).", "Less specific fallback scope.");
rows
| where basis == "Your estate" and picked == true
| take 1
| mv-expand order = dynamic([1, 2, 3, 4]) to typeof(int)
| extend metric = case(order == 1, "Typical year (P50, hours)", order == 2, "Bad year (P90, hours)", order == 3, "Expected events per year", "Based on (past events)"),
         value = case(order == 1, p50_annual_h, order == 2, p90_annual_h, order == 3, events_per_year, todouble(n_events)),
         subtitle = case(order == 1, "Half of years should be at or below this",
                         order == 2, "9 in 10 years should be at or below this",
                         order == 3, strcat("Scope: ", scope_key, "; window ", window_days, " days"),
                         strcat("Confidence: ", confidence, "; durations from ", replace_string(duration_basis, "_", " "))),
         status = case(confidence == "high", "good", confidence == "medium", "info", "warn")
| project order, metric, value, subtitle, status
| order by order asc

let fc = AzMaintenance_Forecast({IncludeSynthetic});
let cat = AzMaintenance_Catalog({IncludeSynthetic}) | summarize category = take_any(category) by service_name;
let svc = '{PlannerService}';
let reg = '{PlannerRegion}';
let svc_cat = toscalar(cat | where service_name == svc | project category);
let rank = (level: string) { case(level == "service_region", 1, level == "service", 2, 3) };
let customer = fc
    | where baseline == "customer"
    | where (scope_level == "service_region" and scope_key == strcat(svc, "|", reg))
         or (scope_level == "service" and scope_key == svc)
         or (scope_level == "category" and scope_key == coalesce(svc_cat, ""))
    | extend r = rank(scope_level)
    | order by r asc
    | extend picked = row_number() == 1;
let weak = toscalar(customer | where picked | project confidence in ("insufficient", "low"));
let pir = fc
    | where baseline == "public_pir" and (scope_key == coalesce(svc_cat, "") or scope_key == "(all categories)")
    | where coalesce(weak, true)
    | extend picked = false;
let rows = union (customer | extend basis = "Your estate"), (pir | extend basis = "Azure-wide PIR baseline, not your estate")
    | extend mean_over_horizon_h = round(mean_annual_h * {PlannerHorizon}, 2),
             note = case(basis startswith "Azure-wide", "Broad-impact incidents only; shown because your history is thin.",
                         picked, "Preferred scope (most specific with data).", "Less specific fallback scope.");
rows
| project basis, scope_level, scope_key, n_events, window_days, confidence, events_per_year, p50_annual_h, p90_annual_h, mean_over_horizon_h, duration_basis, note

let h = AzMaintenance_DataHealth({IncludeSynthetic});
let ingest = h | where section == "ingest";
let ok_n = toscalar(ingest | where status == "OK" | summarize count());
let stale_n = toscalar(ingest | where status == "STALE" | summarize count());
let last_ok = toscalar(ingest | summarize max(last_success_utc));
let subs = toscalar(h | where section == "subscriptions" | project value);
let subs_status = toscalar(h | where section == "subscriptions" | project status);
datatable(order: int)[1, 2, 3, 4]
| extend metric = case(order == 1, "Sources reporting", order == 2, "Stale sources", order == 3, "Last successful update (hours ago)", "Subscriptions covered"),
         value = case(order == 1, todouble(ok_n), order == 2, todouble(stale_n),
                      order == 3, round(todouble(datetime_diff("minute", now(), last_ok)) / 60.0, 1), todouble(subs)),
         subtitle = case(order == 1, "Updated within the last 36 hours", order == 2, "No success in 36 hours: numbers may be out of date",
                         order == 3, "Most recent successful collection", "Subscriptions with data vs configured"),
         status = case(order == 1, iff(ok_n > 0, "good", "bad"), order == 2, iff(stale_n == 0, "good", "bad"),
                       order == 3, iff(isnull(last_ok), "bad", iff(datetime_diff("hour", now(), last_ok) <= 36, "good", "bad")),
                       iff(subs_status == "OK", "good", "warn"))
| project order, metric, value, subtitle, status
| order by order asc
